"use client";

import React, { useEffect, useRef } from "react";

type Stop = { id: string; label: string };

const STOPS: Stop[] = [
    { id: "services", label: "S" },
    { id: "about", label: "AB" },
    { id: "projects", label: "P" },
    { id: "cta", label: "CTA" },
    { id: "footer", label: "F" },
];

const HEIGHT = 240;
const SPACING = HEIGHT / (STOPS.length - 1);

export default function ScrollIndicatorRail({ heroId = "hero" }: { heroId?: string }) {
    const railRef = useRef<HTMLDivElement>(null);
    const lineRef = useRef<SVGPathElement>(null);
    const tickRefs = useRef<(SVGLineElement | null)[]>([]);
    const labelRefs = useRef<(HTMLDivElement | null)[]>([]);

    useEffect(() => {
        function setActive(index: number) {
            const y = index * SPACING;
            lineRef.current?.setAttribute("d", `M 20 0 L 20 ${y}`);

            tickRefs.current.forEach((t, i) => {
                if (t) t.style.opacity = i <= index ? "1" : "0";
            });

            labelRefs.current.forEach((l, i) => {
                if (!l) return;
                l.classList.remove("reached", "active");
                if (i === index) l.classList.add("active");
                else if (i < index) l.classList.add("reached");
            });
        }

        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        const idx = STOPS.findIndex((s) => s.id === entry.target.id);
                        if (idx !== -1) setActive(idx);
                    }
                });
            },
            { threshold: 0.5 }
        );

        STOPS.forEach((s) => {
            const el = document.getElementById(s.id);
            if (el) observer.observe(el);
        });

        const heroEl = document.getElementById(heroId);
        let heroObserver: IntersectionObserver | undefined;
        if (heroEl) {
            heroObserver = new IntersectionObserver(
                ([entry]) => {
                    railRef.current?.classList.toggle("visible", !entry.isIntersecting);
                },
                { threshold: 0.1 }
            );
            heroObserver.observe(heroEl);
        }

        return () => {
            observer.disconnect();
            heroObserver?.disconnect();
        };
    }, [heroId]);

    return (
        <div className="scroll-rail" ref={railRef}>
            <svg width="140" height={HEIGHT + 20} viewBox={`0 0 140 ${HEIGHT + 20}`}>
                <path className="rail-line" ref={lineRef} d="M 20 0 L 20 0" />
                <g>
                    {STOPS.map((s, i) => (
                        <line
                            key={s.id}
                            ref={(el) => {
                                tickRefs.current[i] = el;
                            }}
                            className="rail-tick"
                            x1={20}
                            y1={i * SPACING}
                            x2={34}
                            y2={i * SPACING}
                            style={{ opacity: 0 }}
                        />
                    ))}
                </g>
            </svg>
            <div className="rail-labels-wrap">
                {STOPS.map((s, i) => (
                    <div
                        key={s.id}
                        ref={(el) => {
                            labelRefs.current[i] = el;
                        }}
                        className="rail-label"
                        style={{ top: i * SPACING, left: 34 }}
                    >
                        {s.label}
                    </div>
                ))}
            </div>

            <style jsx>{`
        .scroll-rail {
          position: fixed;
          left: 10px;
          top: 50%;
          transform: translateY(-50%);
          z-index: 50;
          height: ${HEIGHT + 20}px;
          width: 140px;
          opacity: 0;
          pointer-events: none;
          transition: opacity 0.4s ease;
        }
        .scroll-rail.visible {
          opacity: 1;
        }
        .scroll-rail svg {
          position: absolute;
          top: 0;
          left: 0;
          overflow: visible;
        }
        .scroll-rail :global(.rail-line) {
          stroke: #1d5fd6;
          stroke-width: 3;
          stroke-linecap: round;
          fill: none;
          transition: d 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }
        .scroll-rail :global(.rail-tick) {
          stroke: #1d5fd6;
          stroke-width: 2.5;
          stroke-linecap: round;
          transition: opacity 0.3s ease;
        }
        .rail-labels-wrap {
          position: relative;
        }
        .scroll-rail :global(.rail-label) {
          position: absolute;
          font-size: 15px;
          font-weight: 600;
          letter-spacing: 0.04em;
          line-height: 1;
          transform: translate(10px, -50%);
          color: #b9b9b9;
          transition: color 0.3s ease, font-size 0.3s ease, font-weight 0.3s ease;
          white-space: nowrap;
        }
        .scroll-rail :global(.rail-label.reached) {
          color: #1d5fd6;
        }
        .scroll-rail :global(.rail-label.active) {
          color: #171717;
          font-size: 20px;
          font-weight: 700;
        }
        @media (max-width: 700px) {
          .scroll-rail {
            left: 16px;
            width: 110px;
          }
          .scroll-rail :global(.rail-label) {
            font-size: 13px;
          }
          .scroll-rail :global(.rail-label.active) {
            font-size: 17px;
          }
        }
      `}</style>
        </div>
    );
}